{
  "summary": "The paper investigates a channel-aware framework for selecting OR-folded Bloom filter representations under time-varying communication constraints. Using two phishing URL datasets and three channel models, the study demonstrates that adaptive folding improves communication efficiency and receiver freshness compared to complete-filter and lossless-compression baselines. The results highlight the utility of FPR-qualified folded views in scenarios with varying communication opportunities.",
  "items": {
    "chk_problem": {
      "value": "Investigating channel-aware selection of OR-folded Bloom filter representations to improve communication efficiency and receiver freshness in distributed systems with constrained or time-varying communication resources.",
      "paper_quote": "This paper investigates channel-aware selection among OR-folded representations."
    },
    "chk_method": {
      "value": "Channel-aware selection of FPR-qualified OR-folded Bloom filter views based on time-varying communication constraints.",
      "paper_quote": "The sender retains the canonical filter, constructs a catalog of FPR-qualified folded views, and selects the view with the largest retained length supported at each reporting opportunity."
    },
    "chk_data": {
      "value": "Two phishing URL datasets: PhiUSIIL and URL-Phish, with 5,000 malicious URLs for insertion and 50,000 disjoint benign URLs as absent queries.",
      "paper_quote": "The PhiUSIIL [14] and URL-Phish [15] datasets are evaluated using 5,000 malicious URLs for insertion and 50,000 disjoint benign URLs as absent queries."
    },
    "chk_setup": {
      "value": "Evaluation uses two phishing URL datasets, 12 retained-length ratios, four lossless-compression baselines, and three time-varying channel models (Five-State Markov Capacity, Gilbert–Elliott burst-error, and Rayleigh block-fading).",
      "paper_quote": "The evaluation uses two phishing URL datasets, twelve retained-length ratios, four lossless-compression baselines, and three time-varying channel models."
    },
    "chk_primary_result": {
      "value": "Adaptive folding achieves 191.6 successful deliveries per MB under the Five-State Markov Capacity model, compared to 66.9 for the strongest compression baseline and 27.7 for the classical full filter.",
      "paper_quote": "Under the Five-State Markov Capacity model, adaptive folding achieves 191.6 successful deliveries per MB, compared with 66.9 for the strongest compression baseline and 27.7 for the classical full filter."
    },
    "chk_secondary_result": {
      "value": "Adaptive folding reduces mean receiver age to 1.24 intervals under the Five-State Markov Capacity model, compared to 13.5 for the strongest compression baseline and 31.6 for the classical full filter.",
      "paper_quote": "Under the Five-State Markov Capacity model, adaptive folding reduces mean receiver age to 1.24 intervals, compared with 13.5 for the strongest compression baseline and 31.6 for the classical filter."
    },
    "chk_baseline": {
      "value": "Complete-filter and lossless-compression baselines (gzip, zlib, bzip2, and LZMA) are used for comparison.",
      "paper_quote": "The sparse canonical bit array is compared with gzip [17], zlib [18], bzip2 [19], and LZMA [20]."
    },
    "chk_conclusion": {
      "value": "Channel-aware selection of OR-folded views improves communication efficiency and receiver freshness under varying communication conditions, complementing lossless compression.",
      "paper_quote": "This paper evaluated a channel-aware framework that selects the largest FPR-qualified OR-folded view supported at each reporting opportunity while retaining the canonical Bloom filter."
    },
    "chk_limitation": {
      "value": "The study uses fixed datasets, cardinalities, and contents, and does not include real-world channel traces, multiple senders, or imperfect channel estimates.",
      "paper_quote": "The controlled design uses two URL datasets at the same cardinality with fixed contents."
    }
  }
}
